import{_ as t,o as e,c as n,a2 as o}from"./chunks/framework.C0KMm31j.js";const r="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_costmap_first_navfn_smac2d_01_tuning_order.png",i="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_costmap_first_navfn_smac2d_02_costmap_baseline.png",s="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_costmap_first_navfn_smac2d_03_inflation_gradient.png",c="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_costmap_first_navfn_smac2d_04_same_map_two_planners.png",l="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_costmap_first_navfn_smac2d_05_ab_test_matrix.png",d="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_costmap_first_navfn_smac2d_06_selection_decision.png",g=JSON.parse('{"title":"路径贴墙，真是规划器的锅吗？先调好 Costmap，再对决 NavFn A* 与 Smac2D","description":"同一台机器人换了规划器，路径仍然贴墙、穿窄门失败，通常不是两套算法同时失效，而是它们读到了同一张有问题的 Costmap。","frontmatter":{"title":"路径贴墙，真是规划器的锅吗？先调好 Costmap，再对决 NavFn A* 与 Smac2D","description":"同一台机器人换了规划器，路径仍然贴墙、穿窄门失败，通常不是两套算法同时失效，而是它们读到了同一张有问题的 Costmap。","date":"2026-07-21","topic":"Nav2 工程实践","section":"二 · 全局规划与路径搜索","readingTime":5,"source":"2026-07-21/nav2_costmap_first_navfn_smac2d_tuning.md","status":"published","cover":"/article-assets/2026-07-21/nav2_costmap_first_navfn_smac2d_01_tuning_order.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-costmap-first-navfn-smac2d-tuning"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"路径贴墙，真是规划器的锅吗？先调好 Costmap，再对决 NavFn A* 与 Smac2D"}],["meta",{"property":"og:description","content":"同一台机器人换了规划器，路径仍然贴墙、穿窄门失败，通常不是两套算法同时失效，而是它们读到了同一张有问题的 Costmap。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-costmap-first-navfn-smac2d-tuning"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-21/nav2_costmap_first_navfn_smac2d_01_tuning_order.png"}],["meta",{"property":"article:published_time","content":"2026-07-21"}],["meta",{"name":"twitter:title","content":"路径贴墙，真是规划器的锅吗？先调好 Costmap，再对决 NavFn A* 与 Smac2D"}],["meta",{"name":"twitter:description","content":"同一台机器人换了规划器，路径仍然贴墙、穿窄门失败，通常不是两套算法同时失效，而是它们读到了同一张有问题的 Costmap。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-21/nav2_costmap_first_navfn_smac2d_01_tuning_order.png"}]],"prev":{"text":"局部路径为什么会“变形”？拆解 TEB 如何把空间、时间和避障压进一张优化图","link":"/nav2/teb-local-planner-full-dataflow"},"next":{"text":"一颗 A* 大脑，三种机器人怎么共用？拆解 nav2_smac_planner 全调用、状态与数据流","link":"/nav2/nav2-smac-planner-full-dataflow"}},"headers":[],"relativePath":"nav2/nav2-costmap-first-navfn-smac2d-tuning.md","filePath":"nav2/nav2-costmap-first-navfn-smac2d-tuning.md","lastUpdated":null}'),p={name:"nav2/nav2-costmap-first-navfn-smac2d-tuning.md"};function m(h,a,_,f,u,v){return e(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="路径贴墙-真是规划器的锅吗-先调好-costmap-再对决-navfn-a-与-smac2d" tabindex="-1">路径贴墙，真是规划器的锅吗？先调好 Costmap，再对决 NavFn A* 与 Smac2D <a class="header-anchor" href="#路径贴墙-真是规划器的锅吗-先调好-costmap-再对决-navfn-a-与-smac2d" aria-label="Permalink to &quot;路径贴墙，真是规划器的锅吗？先调好 Costmap，再对决 NavFn A* 与 Smac2D&quot;">​</a></h1><p>同一台机器人换了规划器，路径仍然贴墙、穿窄门失败，通常不是两套算法同时失效，而是它们读到了同一张有问题的 Costmap。</p><p>公平比较只有一条原则：先校准机器人几何、地图、障碍和膨胀梯度，冻结公共输入，再只切换 <code>planner_id</code>。否则所谓优劣只是多个变量叠加后的错觉。</p><h2 id="一、先分清比较对象" tabindex="-1">一、先分清比较对象 <a class="header-anchor" href="#一、先分清比较对象" aria-label="Permalink to &quot;一、先分清比较对象&quot;">​</a></h2><h3 id="_1-1-gridbasedastar-是插件-id" tabindex="-1">1.1 GridBasedAstar 是插件 ID <a class="header-anchor" href="#_1-1-gridbasedastar-是插件-id" aria-label="Permalink to &quot;1.1 GridBasedAstar 是插件 ID&quot;">​</a></h3><p>当前配置中的 <code>GridBasedAstar</code> 与 <code>GridBased</code> 都指向 <code>nav2_navfn_planner/NavfnPlanner</code>，不是另一套官方 A*。<code>use_astar: true</code> 才让 NavFn 使用 A* 传播势场。</p><p><code>Smac2D</code> 指向 <code>nav2_smac_planner/SmacPlanner2D</code>，使用带 Costmap 代价的八连通二维 A*。因此本文实际比较的是 NavFn A* 与 Smac2D。</p><h3 id="_1-2-两者共享同一张试卷" tabindex="-1">1.2 两者共享同一张试卷 <a class="header-anchor" href="#_1-2-两者共享同一张试卷" aria-label="Permalink to &quot;1.2 两者共享同一张试卷&quot;">​</a></h3><p>Planner Server 把起点、终点和 Global Costmap 交给选中的插件。StaticLayer、ObstacleLayer、footprint 与 InflationLayer 先决定哪些栅格禁止通行、哪些区域代价较高，规划器再决定如何搜索。</p><p><img src="'+r+'" alt="正确调参顺序"></p><h2 id="二、costmap-基线必须先合格" tabindex="-1">二、Costmap 基线必须先合格 <a class="header-anchor" href="#二、costmap-基线必须先合格" aria-label="Permalink to &quot;二、Costmap 基线必须先合格&quot;">​</a></h2><h3 id="_2-1-机器人几何决定能否通过" tabindex="-1">2.1 机器人几何决定能否通过 <a class="header-anchor" href="#_2-1-机器人几何决定能否通过" aria-label="Permalink to &quot;2.1 机器人几何决定能否通过&quot;">​</a></h3><p>优先核对 footprint 或 robot radius、<code>footprint_padding</code>、地图分辨率与真实车宽。模型偏小会让路径看似可行却导致实车擦碰；模型偏大则会封死本来能过的窄通道。</p><h3 id="_2-2-地图与障碍层必须可信" tabindex="-1">2.2 地图与障碍层必须可信 <a class="header-anchor" href="#_2-2-地图与障碍层必须可信" aria-label="Permalink to &quot;2.2 地图与障碍层必须可信&quot;">​</a></h3><ul><li>StaticLayer 的地图原点、分辨率、占用阈值与实际环境一致。</li><li>ObstacleLayer 能标记障碍，也能通过 raytracing 清除旧障碍。</li><li>激光 frame、时间戳和 TF 正常，不在地图上制造重影。</li><li>Master Costmap 中未知区、致命障碍与自由空间符合预期。</li></ul><p>只有这四类输入稳定后，规划器对比才有意义。</p><p><img src="'+i+'" alt="规划器对决前的 Costmap 基线"></p><h2 id="三、inflation-两个参数最容易调反" tabindex="-1">三、Inflation 两个参数最容易调反 <a class="header-anchor" href="#三、inflation-两个参数最容易调反" aria-label="Permalink to &quot;三、Inflation 两个参数最容易调反&quot;">​</a></h2><h3 id="_3-1-inflation-radius-决定覆盖范围" tabindex="-1">3.1 inflation_radius 决定覆盖范围 <a class="header-anchor" href="#_3-1-inflation-radius-决定覆盖范围" aria-label="Permalink to &quot;3.1 inflation_radius 决定覆盖范围&quot;">​</a></h3><p>它决定障碍物周围多远仍保留膨胀代价。半径过小，宽通道中央几乎没有代价差，规划器缺少远离墙面的动力；半径过大，窄通道可能被高代价区压缩甚至封闭。</p><h3 id="_3-2-cost-scaling-factor-决定衰减速度" tabindex="-1">3.2 cost_scaling_factor 决定衰减速度 <a class="header-anchor" href="#_3-2-cost-scaling-factor-决定衰减速度" aria-label="Permalink to &quot;3.2 cost_scaling_factor 决定衰减速度&quot;">​</a></h3><p>代价大致按指数衰减。<code>cost_scaling_factor</code> 越大，离开障碍后下降越快；越小，高代价影响延伸越远。它不是“越大越安全”。</p><p>调试时先保证窄通道仍连通，再观察宽通道是否形成连续、对称的代价坡度，最后冻结这两个参数。</p><p><img src="'+s+'" alt="Inflation 代价梯度"></p><h2 id="四、两套-a-怎样使用代价" tabindex="-1">四、两套 A* 怎样使用代价 <a class="header-anchor" href="#四、两套-a-怎样使用代价" aria-label="Permalink to &quot;四、两套 A* 怎样使用代价&quot;">​</a></h2><h3 id="_4-1-navfn-a-传播势场" tabindex="-1">4.1 NavFn A* 传播势场 <a class="header-anchor" href="#_4-1-navfn-a-传播势场" aria-label="Permalink to &quot;4.1 NavFn A* 传播势场&quot;">​</a></h3><p>NavFn 先把 Costmap 值映射到内部代价，再从目标向外传播 potential。启发项改变节点展开优先级，最终通过梯度回溯形成连续 Path。它成熟、简单，但净空偏好主要受固定代价映射和 Inflation 地形影响。</p><h3 id="_4-2-smac2d-显式计算代价感知移动成本" tabindex="-1">4.2 Smac2D 显式计算代价感知移动成本 <a class="header-anchor" href="#_4-2-smac2d-显式计算代价感知移动成本" aria-label="Permalink to &quot;4.2 Smac2D 显式计算代价感知移动成本&quot;">​</a></h3><p>Smac2D 使用 <code>g+h</code> 搜索。每次八邻域移动不仅计算直走或斜走距离，还将归一化 Costmap 代价乘入 <code>cost_travel_multiplier</code>。因此在仍可通行的栅格中，它能更直接地权衡路程与净空。</p><p>搜索结果还会进入内置 Smoother，所以最终 Path 的圆滑程度不能全部归因于 A* 搜索本身。</p><p><img src="'+c+'" alt="同一张 Costmap 下的两套规划器"></p><h2 id="五、公平-a-b-只改变-planner-id" tabindex="-1">五、公平 A/B 只改变 planner_id <a class="header-anchor" href="#五、公平-a-b-只改变-planner-id" aria-label="Permalink to &quot;五、公平 A/B 只改变 planner_id&quot;">​</a></h2><h3 id="_5-1-固定公共条件" tabindex="-1">5.1 固定公共条件 <a class="header-anchor" href="#_5-1-固定公共条件" aria-label="Permalink to &quot;5.1 固定公共条件&quot;">​</a></h3><p>地图、起终点、footprint、Costmap 分辨率、障碍源、Inflation、TF、定位和最大规划时间必须一致。不要一边换规划器，一边调整膨胀或平滑参数。</p><h3 id="_5-2-使用统一场景与指标" tabindex="-1">5.2 使用统一场景与指标 <a class="header-anchor" href="#_5-2-使用统一场景与指标" aria-label="Permalink to &quot;5.2 使用统一场景与指标&quot;">​</a></h3><p>测试应覆盖宽通道、窄门、贴墙起终点、拐角和长距离绕障。每组重复运行，记录：</p><ul><li>成功率与规划耗时。</li><li>最小障碍净空与路径长度。</li><li>搜索扩展数或超时情况。</li><li>路径曲率、抖动和执行成功率。</li></ul><p>截图漂亮不是可靠指标；同场景多次结果才有统计意义。</p><p><img src="'+l+'" alt="规划器单变量 A/B 测试"></p><h2 id="六、costmap-固定后再调插件参数" tabindex="-1">六、Costmap 固定后再调插件参数 <a class="header-anchor" href="#六、costmap-固定后再调插件参数" aria-label="Permalink to &quot;六、Costmap 固定后再调插件参数&quot;">​</a></h2><h3 id="_6-1-navfn-先作为稳定基线" tabindex="-1">6.1 NavFn 先作为稳定基线 <a class="header-anchor" href="#_6-1-navfn-先作为稳定基线" aria-label="Permalink to &quot;6.1 NavFn 先作为稳定基线&quot;">​</a></h3><p>保持 <code>allow_unknown</code>、<code>tolerance</code>、<code>use_astar</code> 和 <code>use_final_approach_orientation</code> 明确，先确认它能稳定生成可执行路径。若它与 Smac2D 都失败，应回到公共输入排查。</p><h3 id="_6-2-smac2d-再调代价权衡" tabindex="-1">6.2 Smac2D 再调代价权衡 <a class="header-anchor" href="#_6-2-smac2d-再调代价权衡" aria-label="Permalink to &quot;6.2 Smac2D 再调代价权衡&quot;">​</a></h3><p><code>cost_travel_multiplier</code> 越大，搜索越不愿进入高代价区，但可能产生更长绕行。<code>downsample_costmap</code> 会改变搜索分辨率和速度，也会牺牲窄结构细节。搜索与 Smoother 参数应分开调，避免把路径形状变化归错层。</p><h2 id="七、按现象定位责任层" tabindex="-1">七、按现象定位责任层 <a class="header-anchor" href="#七、按现象定位责任层" aria-label="Permalink to &quot;七、按现象定位责任层&quot;">​</a></h2><h3 id="_7-1-两套规划器都贴墙" tabindex="-1">7.1 两套规划器都贴墙 <a class="header-anchor" href="#_7-1-两套规划器都贴墙" aria-label="Permalink to &quot;7.1 两套规划器都贴墙&quot;">​</a></h3><p>优先查 footprint、Inflation 梯度和静态地图边界，而不是继续放大某个插件权重。</p><h3 id="_7-2-两套规划器都过不了窄门" tabindex="-1">7.2 两套规划器都过不了窄门 <a class="header-anchor" href="#_7-2-两套规划器都过不了窄门" aria-label="Permalink to &quot;7.2 两套规划器都过不了窄门&quot;">​</a></h3><p>检查 footprint、padding、分辨率和 inflation radius 是否共同封闭通道。</p><h3 id="_7-3-只有-smac2d-绕行明显" tabindex="-1">7.3 只有 Smac2D 绕行明显 <a class="header-anchor" href="#_7-3-只有-smac2d-绕行明显" aria-label="Permalink to &quot;7.3 只有 Smac2D 绕行明显&quot;">​</a></h3><p>检查 <code>cost_travel_multiplier</code> 是否过大，以及内置平滑是否改变了路径外形。</p><h3 id="_7-4-全局路径正常但实车擦碰" tabindex="-1">7.4 全局路径正常但实车擦碰 <a class="header-anchor" href="#_7-4-全局路径正常但实车擦碰" aria-label="Permalink to &quot;7.4 全局路径正常但实车擦碰&quot;">​</a></h3><p>问题已经进入 Local Costmap、Controller、速度、定位延迟或底盘跟踪层，不应继续调全局规划器。</p><h2 id="八、选型没有绝对冠军" tabindex="-1">八、选型没有绝对冠军 <a class="header-anchor" href="#八、选型没有绝对冠军" aria-label="Permalink to &quot;八、选型没有绝对冠军&quot;">​</a></h2><h3 id="_8-1-navfn-a-适合成熟简洁的基线" tabindex="-1">8.1 NavFn A* 适合成熟简洁的基线 <a class="header-anchor" href="#_8-1-navfn-a-适合成熟简洁的基线" aria-label="Permalink to &quot;8.1 NavFn A* 适合成熟简洁的基线&quot;">​</a></h3><p>它依赖少、行为稳定、调参面较小，适合快速建立可靠基线与资源受限平台。</p><h3 id="_8-2-smac2d-适合更明确的净空权衡" tabindex="-1">8.2 Smac2D 适合更明确的净空权衡 <a class="header-anchor" href="#_8-2-smac2d-适合更明确的净空权衡" aria-label="Permalink to &quot;8.2 Smac2D 适合更明确的净空权衡&quot;">​</a></h3><p>它让 Costmap 代价直接进入移动成本，并提供降采样与内置平滑，更适合需要通道居中、愿意用计算量换路径质量的场景。</p><p><img src="'+d+'" alt="Costmap 合格后的选型路径"></p><h2 id="九、最终结论" tabindex="-1">九、最终结论 <a class="header-anchor" href="#九、最终结论" aria-label="Permalink to &quot;九、最终结论&quot;">​</a></h2><h3 id="_9-1-正确顺序比-选谁-更重要" tabindex="-1">9.1 正确顺序比“选谁”更重要 <a class="header-anchor" href="#_9-1-正确顺序比-选谁-更重要" aria-label="Permalink to &quot;9.1 正确顺序比“选谁”更重要&quot;">​</a></h3><p>Costmap 决定哪里能走、哪里更贵；规划器决定怎样在这片代价地形中搜索。先把地图、几何、障碍和 Inflation 调可信，再做单变量 A/B，NavFn A* 与 Smac2D 的差异才可复现、可解释。</p><h3 id="_9-2-参考资料" tabindex="-1">9.2 参考资料 <a class="header-anchor" href="#_9-2-参考资料" aria-label="Permalink to &quot;9.2 参考资料&quot;">​</a></h3><p><a href="https://docs.nav2.org/configuration/packages/configuring-costmaps.html" target="_blank" rel="noreferrer">Nav2 Costmap 2D 配置</a></p><p><a href="https://docs.nav2.org/configuration/packages/configuring-navfn.html" target="_blank" rel="noreferrer">Nav2 NavFn Planner 配置</a></p><p><a href="https://docs.nav2.org/configuration/packages/smac/configuring-smac-2d.html" target="_blank" rel="noreferrer">Nav2 Smac 2D Planner 配置</a></p>',66)])])}const q=t(p,[["render",m]]);export{g as __pageData,q as default};
